import{_ as t,o as e,c as n,ag as r}from"./chunks/framework.D5hoimZQ.js";const g=JSON.parse('{"title":"🔬 科学日报 | 2026年7月1日 · 深度扩展","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/science-daily/2026-07-01.md","filePath":"science-log/src/science-daily/2026-07-01.md"}'),a={name:"science-log/src/science-daily/2026-07-01.md"};function i(s,o,c,u,d,p){return e(),n("div",null,[...o[0]||(o[0]=[r('<h1 id="🔬-科学日报-2026年7月1日-·-深度扩展" tabindex="-1">🔬 科学日报 | 2026年7月1日 · 深度扩展 <a class="header-anchor" href="#🔬-科学日报-2026年7月1日-·-深度扩展" aria-label="Permalink to &quot;🔬 科学日报 | 2026年7月1日 · 深度扩展&quot;">​</a></h1><blockquote><p>来源：科学快报 第 11 期简讯（2026-07-01，共 11 条：科学前沿 6 篇 / AI 前沿 5 篇） 分析日期：2026-07-01 版本：扩展版（11 条深度 + 交叉关联） 核验：2026-11-07 经 CrossRef（DOI 逐条取题名/卷页/作者）、EuropePMC、arXiv abs 页核对，<strong>与简讯原文有出入处以核实结果为准并在正文标明</strong></p></blockquote><hr><h2 id="🔬-一、科学前沿" tabindex="-1">🔬 一、科学前沿 <a class="header-anchor" href="#🔬-一、科学前沿" aria-label="Permalink to &quot;🔬 一、科学前沿&quot;">​</a></h2><h3 id="_1-多层镍酸盐超导相图首次完整勾勒" tabindex="-1">1. 多层镍酸盐超导相图首次完整勾勒 <a class="header-anchor" href="#_1-多层镍酸盐超导相图首次完整勾勒" aria-label="Permalink to &quot;1. 多层镍酸盐超导相图首次完整勾勒&quot;">​</a></h3><p><strong>原文</strong>：Science 报道了一项镍酸盐超导体的重要突破（DOI: 10.1126/science.adp4440）。研究团队系统绘制了多层四方平面镍酸盐 (La,Pr,Sm)₃Ni₂O₇ 薄膜的超导相图，揭示了在不同电子掺杂和压力条件下的超导转变行为。</p><p><strong>深度扩展</strong>：</p><p>核验后需修正简讯的一处混淆：<code>10.1126/science.adp4440</code> 的题名是 <em>Superconducting phase diagram of multilayer square-planar nickelates</em>（Science 392 卷 1390–1395 页，2026-06-25 上线），作者 24 人，第一作者 Grace A. Pan、Dan Ferenc Segedin，单位是哈佛大学物理系（Julia Mundy 组）；研究对象<strong>不是</strong> (La,Pr,Sm)₃Ni₂O₇，而是 Ndₙ₊₁NiₙO₂ₙ₊₂ 多层膜的维度序列。简讯里提到的 (La,Pr,Sm)₃Ni₂O₇ 属于同期的姊妹论文 <code>10.1126/science.adw8329</code>（Science 392 卷 1396–1400 页，沈建昌等，中国科学技术大学/合肥国家实验室）。</p><p>两篇合起来才是完整图景。哈佛组把 n=4 到 n=8 的多层结构逐层做出来，发现每一层都能超导；随 n 减小，超导各向异性因 4f 电子效应而系统性演化，电子结构逐步靠近铜氧化物（cuprate-like）；磁涨落不只在超导区存在，一直延伸到过掺杂的非超导区——这是&quot;磁涨落驱动配对&quot;最直接的相图级证据。</p><p>中科大组则用超高真空低温解理-转移技术，对 (La,Pr,Sm)₃Ni₂O₇ 薄膜做角分辨光电子能谱，沿布里渊区对角线测到约 18 meV 的超导能隙与相干峰，且能隙在整个布里渊区都有限、没有节点，从而判定为无节点配对，并提取出电子-玻色子耦合谱。</p><p><strong>跨主题关联</strong>：与 <code>topics/quantum-physics/index.md</code> 的配对机制讨论、<code>topics/materials/index.md</code> 的强关联氧化物薄膜工艺同源；2026-07-02 的日报也覆盖了这条 DOI，可对读。</p><hr><h3 id="_2-gw250114-直接测到黑洞视界的-拖曳回响" tabindex="-1">2. GW250114：直接测到黑洞视界的&quot;拖曳回响&quot; <a class="header-anchor" href="#_2-gw250114-直接测到黑洞视界的-拖曳回响" aria-label="Permalink to &quot;2. GW250114：直接测到黑洞视界的&quot;拖曳回响&quot;&quot;">​</a></h3><p><strong>原文</strong>：Nature 发表了 LIGO-Virgo-KAGRA 合作组对 GW250114 事件的深度分析。这是迄今信噪比最高的黑洞合并事件，科学家成功从合并后的&quot;铃荡&quot;（ringdown）阶段提取出视界存在的高置信度特征。</p><p><strong>深度扩展</strong>：</p><p><code>10.1038/s41586-026-10696-0</code>（<em>GW250114 reveals signatures of post-merger black-hole horizon</em>，Nature 655 卷 71–75 页，2026-06-24）只有 5 位作者：Neil Lu、Sizheng Ma、Ornella J. Piccinni、陈雁北（Yanbei Chen）、孙凌（Ling Sun）——这是一篇理论/数据分析文章，不是合作组官方探测论文，简讯把它写成&quot;合作组分析&quot;并不准确。</p><p>它检验的也不是普通的准正常模（QNM），而是 2025 年理论预言的**&quot;直接波&quot;（direct wave）**：落入黑洞的物体会被参考系拖曳强行锁定在以视界角速度 Ω_H 旋转的轨道上，它发出的引力波因此以接近 2Ω_H 的频率振荡，并按视界表面重力 κ 决定的速率指数衰减——这是&quot;视界本身&quot;的印记，而不是轨道动力学的遗留。</p><p>匹配滤波结果：LIGO Hanford 在 90% 置信度下信噪比 15.8 (+0.1/−0.5)，Livingston 为 17.1 (+0.1/−0.4)。测得的频率与衰减率与 Kerr 黑洞的理论预言完全一致。这为&quot;无毛定理&quot;提供了迄今为止最直接的一类检验，也打开了一条在强场动力学区测量能层参考系拖曳的观测通道。</p><p><strong>跨主题关联</strong>：<code>topics/physics/index.md</code>（广义相对论检验）、<code>topics/philosophy/index.md</code>（&quot;不可见之物如何被间接观测&quot;的认识论问题）。</p><hr><h3 id="_3-人眼视锥色素冷冻电镜结构-颜色视觉的分子底座" tabindex="-1">3. 人眼视锥色素冷冻电镜结构：颜色视觉的分子底座 <a class="header-anchor" href="#_3-人眼视锥色素冷冻电镜结构-颜色视觉的分子底座" aria-label="Permalink to &quot;3. 人眼视锥色素冷冻电镜结构：颜色视觉的分子底座&quot;">​</a></h3><p><strong>原文</strong>：Science 同期发表三篇姊妹文章，首次用冷冻电镜解析了人眼红、绿、蓝三种视锥色素的高分辨率结构，揭示了视黄醛（retinal）发色团如何与蛋白口袋结合并被&quot;调谐&quot;到不同波长范围。</p><p><strong>深度扩展</strong>：</p><p>三篇同期刊于 Science 392 卷（均为 2026-06-25 上线），但分工并不对称，核验后的题名如下：</p><ul><li><code>10.1126/science.adz3624</code> <em>Illuminating the molecular basis of human daylight vision</em>（Schmidt、Dostal、Sen 等 12 人，主要单位 Paul Scherrer 研究所与 ETH Zürich）：解析人蓝敏 OPN1SW 与绿敏 OPN1MW 的暗态冷冻电镜结构，叠加飞秒分辨光谱、功能测定与分子模拟。</li><li><code>10.1126/science.adz3996</code> <em>Structural insights into spectral tuning and retinal exchange in cone visual pigments</em>（大橋さやか、片山航太等）：聚焦光谱调谐与视黄醛交换路径。</li><li><code>10.1126/science.adz8141</code> <em>Cryo–electron microscopy structures of human cone visual pigments</em>（彭琦、李健、蒋海海等）：人视锥色素的结构学总图。</li></ul><p>核心发现是三件事。其一，三种视锥共用同一个发色团 11-顺视黄醛，波长差异完全来自蛋白口袋的静电环境——口袋内极性残基的位置决定 Schiff 碱质子化态的能量，从而把吸收峰在蓝（~420 nm）、绿（~530 nm）、红（~560 nm）之间挪动。其二，三种色素的发色团稳定机制各不相同，说明&quot;同一个零件、三套装配工艺&quot;。其三，GPCR 的&quot;微开关&quot;（microswitch）基序在视锥中发生了序列特化，这解释了视锥为何能在强光下快速失活（毫秒级），而不像视杆视紫红质那样慢。</p><p>意义在于：色盲、视网膜色素变性的突变位点大多落在这些被结构定位的口袋残基与微开关上，结构一旦可读，基因治疗与小分子&quot;光谱位移&quot;设计就有了坐标。</p><p><strong>跨主题关联</strong>：<code>topics/neuroscience/index.md</code>（感觉转导）、<code>topics/biomedicine/index.md</code>（GPCR 药理学的通用价值）。</p><hr><h3 id="_4-单细胞多组学-精神疾病风险位点的-情境开关" tabindex="-1">4. 单细胞多组学：精神疾病风险位点的&quot;情境开关&quot; <a class="header-anchor" href="#_4-单细胞多组学-精神疾病风险位点的-情境开关" aria-label="Permalink to &quot;4. 单细胞多组学：精神疾病风险位点的&quot;情境开关&quot;&quot;">​</a></h3><p><strong>原文</strong>：Science 上的大规模单细胞研究（DOI: 10.1126/science.adw3949）分析了不同脑区、不同激活状态下神经元的染色质可及性、RNA 表达和蛋白丰度，构建了&quot;上下文-基因-疾病&quot;的三维图谱。</p><p><strong>深度扩展</strong>：</p><p><code>10.1126/science.adw3949</code> 的实测内容与简讯描述有偏差，需更正：题名 <em>Single-cell multiomics of neuron activation reveals context-specific genetics of brain disorders</em>（Science 392 卷，2026-06-25），第一作者梁丽凡（Lifan Liang）、张思伟（Siwei Zhang），通讯单位为芝加哥大学人类遗传学系与 Endeavor Health 精神遗传学中心，共 21 位作者。研究材料<strong>不是</strong>人脑切片，而是 100 位供者的<strong>诱导多能干细胞（iPSC）分化神经元</strong>，做单核 RNA+ATAC 多组学，并对比&quot;静息 vs 刺激激活&quot;两种状态。</p><p>三个关键数字与结论：一，在激活状态下鉴定出大量与活性依赖基因表达、染色质可及性相关的遗传变异；二，其中染色质可及性那一类，解释的精神疾病遗传力<strong>比例更高</strong>——也就是说，非编码区的&quot;开关&quot;比编码区的&quot;零件&quot;更能解释风险；三，与 GWAS 整合后，浮现出一批<strong>只在刺激后才显效</strong>的风险基因，典型例子是活性依赖的胆固醇代谢通路。</p><p>这直接改写了&quot;风险基因&quot;的定义：它不是恒定表达的坏零件，而是被错误调度的开关。对药物开发的含义是，靶点筛选必须在&quot;正确的激活窗口&quot;里做，用静息态细胞筛，会漏掉大部分真正的效应。</p><p><strong>跨主题关联</strong>：<code>topics/neuroscience/index.md</code>、<code>topics/biomedicine/index.md</code>；方法学上与 <code>topics/intelligence-self-learning/index.md</code> 的&quot;上下文决定表征&quot;同构。</p><hr><h3 id="_5-菱面体石墨烯-磁场-助力-超导的新家族" tabindex="-1">5. 菱面体石墨烯：磁场&quot;助力&quot;超导的新家族 <a class="header-anchor" href="#_5-菱面体石墨烯-磁场-助力-超导的新家族" aria-label="Permalink to &quot;5. 菱面体石墨烯：磁场&quot;助力&quot;超导的新家族&quot;">​</a></h3><p><strong>原文</strong>：Nature 报道了在菱面体多层石墨烯中发现的&quot;磁场增强超导&quot;家族（DOI: 10.1038/s41586-026-10815-x）。通常磁场会破坏超导，但在这类系统中，平行磁场不仅没有削弱，反而显著提升超导转变温度。</p><p><strong>深度扩展</strong>：</p><p><code>10.1038/s41586-026-10815-x</code>（<em>Family of magnetic field-boosted superconductors in rhombohedral graphene</em>，Nature 656 卷 60–66 页，2026-06-29）共 21 位作者，第一作者 Junseok Seo、Armel A. Cotten，通讯作者为康奈尔大学的 L. Ju（巨磊）；器件由 Watanabe/Taniguchi 提供 hBN 晶体，理论/测量侧还有 D. M. Zumbühl 参与。</p><p>实验对象是菱面体（rhombohedral）<strong>四层与五层</strong>石墨烯的输运测量。关键结果有三条：一，在五层体系中找到<strong>三种</strong>不同类型的磁场增强型与磁场诱导型超导；二，它们对<strong>面内</strong>磁场直到 8.5 T 仍然稳定，超出 Pauli 极限数十倍——Pauli 极限是&quot;磁场拆散库珀对&quot;的经典上限，超出几十倍意味着配对电子并非简单自旋单态；三，与 Bernal 双层石墨烯只在面内磁场下增强不同，五层体系在<strong>面外</strong>磁场下也能被增强，且因为能带更平坦，所需的栅极电场低得多，实验窗口宽、可工程化。此外，引入邻近自旋轨道耦合还能在不增加无序的前提下&quot;生&quot;出多个新超导相。</p><p>物理含义是：若时间反演对称性可以与规范对称性分离地破缺，就会出现&quot;磁场是助力而非敌人&quot;的超导——这正是非常规配对（如 FFLO、同位旋/自旋-谷锁定）的判据场。石墨烯因此从&quot;复现铜氧化物的玩具&quot;变成&quot;可调参数最干净的非常规超导平台&quot;。</p><p><strong>跨主题关联</strong>：<code>topics/physics/index.md</code>、<code>topics/quantum-physics/index.md</code>、<code>topics/materials/index.md</code>（二维材料与拓扑超导）。</p><hr><h3 id="_6-2400-°c-仍保-100-mpa-可铸可加工的-ta-基合金" tabindex="-1">6. 2400 °C 仍保 100 MPa：可铸可加工的 Ta 基合金 <a class="header-anchor" href="#_6-2400-°c-仍保-100-mpa-可铸可加工的-ta-基合金" aria-label="Permalink to &quot;6. 2400 °C 仍保 100 MPa：可铸可加工的 Ta 基合金&quot;">​</a></h3><p><strong>原文</strong>：Nature 报道了一种新型韧性合金（DOI: 10.1038/s41586-026-10708-z），在 2400°C 仍能维持 100 MPa 的抗拉强度——这是现有镍基高温合金的极限温度 1100°C 的两倍以上。</p><p><strong>深度扩展</strong>：</p><p><code>10.1038/s41586-026-10708-z</code>（<em>Ductile alloys offering 100 MPa tensile strength at 2,400 °C</em>，Nature 655 卷 109–115 页，2026-06-24），作者 7 人：薛敏涛、李苏植、王静、李金阳、丁向东、En Ma（毛恩）、孙军。这是一支纯国内的强关联&quot;计算+实验&quot;组合，长期做难熔金属与纳米析出强化。</p><p>工艺是本文的真正创新点：<strong>硼介入的原位氧化反应</strong>（boron-intervened in situ oxidation）。用硼先稳住 HfO₂（氧化铪），在 Ta 基体里原位生成约 <strong>50 nm</strong> 直径的氧化物颗粒，并让它们在<strong>晶粒内部</strong>密集、均匀地弥散。这解决了难熔合金几十年的死结：陶瓷相能提供高温强度，但加进去就变脆；金属基体韧性好，但 2000 °C 以上强度塌方。</p><p>三个结果：一，2400 °C 下抗拉强度仍有 100 MPa，填补了该温区的空白；二，室温下仍保持可加工塑性，可用铸造+变形工艺做成复杂形状件，而不是只能烧结的脆块；三，晶内弥散（而非晶界偏聚）使得颗粒在长期高温下不易粗化，抗 Ostwald 熟化能力显著优于传统析出相。</p><p>工程意义落在三处：高超声速飞行器的前缘与燃烧室、可重复使用火箭发动机喷管、核反应堆包壳。涡轮前温度每提高 100 °C，热效率约升 1–2%，这类材料把上限从 1100 °C 推到 2400 °C，是数量级的空间。</p><p><strong>跨主题关联</strong>：<code>topics/materials/index.md</code>（高温合金/难熔金属）、<code>topics/wind-energy/index.md</code>（燃气轮机与热端部件材料需求）、<code>topics/space-energy/index.md</code>（火箭发动机与再入热防护）。</p><hr><h2 id="🤖-二、ai-前沿" tabindex="-1">🤖 二、AI 前沿 <a class="header-anchor" href="#🤖-二、ai-前沿" aria-label="Permalink to &quot;🤖 二、AI 前沿&quot;">​</a></h2><h3 id="_7-ai-模型网络-ai-modelnet-把-计算机-连成-互联网" tabindex="-1">7. AI 模型网络（AI-ModelNet）：把&quot;计算机&quot;连成&quot;互联网&quot; <a class="header-anchor" href="#_7-ai-模型网络-ai-modelnet-把-计算机-连成-互联网" aria-label="Permalink to &quot;7. AI 模型网络（AI-ModelNet）：把&quot;计算机&quot;连成&quot;互联网&quot;&quot;">​</a></h3><p><strong>原文</strong>：arXiv: <a href="https://arxiv.org/abs/2606.27382" target="_blank" rel="noreferrer">2606.27382</a> 论文提出 AI-Model Network（AMN）的概念与架构框架，类比互联网对计算机的赋能：单个大模型是&quot;计算机&quot;，而 AMN 则是&quot;互联网&quot;。</p><p><strong>深度扩展</strong>：</p><p>核验后的正式题名是 <em>AI-Model Network: Concept, Current State and Future</em>（arXiv:2606.27382，abs 页已核对存在且题名一致）。作者的立论起点很朴素：大模型的实际落地被两件事卡住——训练成本高、部署复杂；于是行业转向轻量、私有、领域专用模型。结果是异构模型数量爆炸式增长，&quot;让它们互相发现、互相调用&quot;成为新的瓶颈。</p><p>论文的类比链条是：计算机之于互联网 ≈ 单模型之于模型网络。互联网的价值不在单机算力，而在 TCP/IP 这种<strong>标准化协议</strong>让任意两台机器可以通信；同理，模型网络的价值不在单个权重，而在让任意两个模型可以交换能力。为此它给出概念、愿景与系统架构三层，讨论能力注册与发现、调用编排、以及计费与治理这类&quot;互联网级&quot;必需件。</p><p>值得注意的是，这是一篇<strong>立场与架构</strong>文章（concept paper），核心贡献是问题定义与分层设计，而非新的实验结果或基准分数——读它应当读它的接口抽象，不要期待 SOTA 数字。</p><p><strong>跨主题关联</strong>：<code>topics/ai-system-architecture/index.md</code>（系统分层与协议设计）、<code>topics/ai-tools/index.md</code>（工具生态的类比）。</p><hr><h3 id="_8-多智能体团队的-人格组合-任务结构决定一切" tabindex="-1">8. 多智能体团队的&quot;人格组合&quot;：任务结构决定一切 <a class="header-anchor" href="#_8-多智能体团队的-人格组合-任务结构决定一切" aria-label="Permalink to &quot;8. 多智能体团队的&quot;人格组合&quot;：任务结构决定一切&quot;">​</a></h3><p><strong>原文</strong>：arXiv: <a href="https://arxiv.org/abs/2606.27443" target="_blank" rel="noreferrer">2606.27443</a> 研究者系统测试了在多智能体系统中给不同 agent 分配不同&quot;人格提示&quot;对协作任务表现的影响。结果出人意料：人格组合是否有效高度依赖任务领域。</p><p><strong>深度扩展</strong>：</p><p>正式题名 <em>When Does Personality Composition Matter for Multi-Agent LLM Teams?</em>（arXiv:2606.27443，abs 页核对一致）。实验设计是干净的三因子：人格维度（宜人性高/低等）× 前沿 LLM × 三个任务域，三个域分别是<strong>结构化编程</strong>、<strong>开放式研究协作</strong>、<strong>竞争性谈判</strong>。</p><p>结论比简讯转述的更精确，也更反直觉：</p><ul><li>编程任务里，低宜人性人格产生<strong>大幅度的沟通风格偏移</strong>，但里程碑完成率几乎不变——说话变凶了，活还是干完了。也就是说&quot;沟通风格&quot;与&quot;任务产出&quot;在这类任务里解耦。</li><li>开放式协作与谈判里，同一个操纵却<strong>显著降低</strong>表现。原因不难推：这两类任务依赖信息交换与让步，而人格提示直接改写了&quot;愿不愿意让出信息&quot;的收益函数。</li><li>由此可以提炼出一个可操作的判据：<strong>任务结构越接近&quot;可分解 + 可验证&quot;，人格操纵越无害；越接近&quot;需要协商 + 信息不对称&quot;，人格操纵越有害</strong>。</li></ul><p>这篇的方法论价值大于结论价值：它把&quot;给 agent 设人格&quot;从凭直觉的工艺，变成了可以在三个轴上做对照实验的变量。对 CrewAI / AutoGen / LangGraph 这类框架的直接含义是，人格配置应当按任务类型分档，而不是全局统一。</p><p><strong>跨主题关联</strong>：<code>topics/ai-system-architecture/index.md</code>（多智能体编排）、<code>topics/psychology/index.md</code>（人格维度与群体决策）。</p><hr><h3 id="_9-内化未来-把世界模型压进自回归模型本身" tabindex="-1">9. 内化未来：把世界模型压进自回归模型本身 <a class="header-anchor" href="#_9-内化未来-把世界模型压进自回归模型本身" aria-label="Permalink to &quot;9. 内化未来：把世界模型压进自回归模型本身&quot;">​</a></h3><p><strong>原文</strong>：arXiv: <a href="https://arxiv.org/abs/2606.27483" target="_blank" rel="noreferrer">2606.27483</a> 这篇论文训练单个自回归模型同时<strong>输出计划 + 模拟该计划的未来轨迹</strong>，让模型在生成动作前先&quot;在脑子里走一遍&quot;。在多个长视野决策基准上显著优于 ReAct、Reflexion 等基线。</p><p><strong>深度扩展</strong>：</p><p>正式题名 <em>Internalizing the Future: A Unified Agentic Training Paradigm for World Model Planning</em>（arXiv:2606.27483）。问题陈述很锐利：LLM agent 在长视野任务中是<strong>反应式</strong>的，缺少人类的&quot;what-if&quot;——先模拟再承诺。标准解法是外挂一个 simulator，但那是两套系统、两次调用、两倍延迟。</p><p>作者的做法是把两样东西都verbalize（言语化）出来：一段<strong>前瞻性状态推演</strong>（state rollout），加一个<strong>计划条件下的成功估计</strong>（plan-conditioned success estimate）——后者被明确定位为 Q 值的文本类比。</p><p>真正有价值的是它发现并命名的一个坑：<strong>格式-能力落差</strong>（format-capability gap）。如果只在后训练阶段拿&quot;前瞻轨迹&quot;做微调，模型会学到<strong>表面上的深谋远虑</strong>——输出格式对了，但并没有真正的预测性 grounding，等于学会了&quot;像在思考&quot;而不是&quot;在思考&quot;。为填这个落差，论文提出三阶段训练：先用 World Model Agentic Mid-Training（WM-AMT）把潜在预测能力注入策略；再用 Format-Eliciting SFT（FE-SFT）把这份能力结构化表达出来；第三阶段做对齐收口。</p><p>这条&quot;先灌能力、再教格式&quot;的顺序，是对当下主流&quot;直接 SFT 轨迹数据&quot;的一记提醒：<strong>格式可以模仿，能力不能</strong>。</p><p><strong>跨主题关联</strong>：<code>topics/intelligence-self-learning/index.md</code>（自我改进的闭环结构）、<code>topics/ai-brain/index.md</code>（&quot;外脑&quot;是否需要内建世界模型）。</p><hr><h3 id="_10-odyssey-用范畴论拼装-可验证、局部保真-的基础模型" tabindex="-1">10. ODYSSEY：用范畴论拼装&quot;可验证、局部保真&quot;的基础模型 <a class="header-anchor" href="#_10-odyssey-用范畴论拼装-可验证、局部保真-的基础模型" aria-label="Permalink to &quot;10. ODYSSEY：用范畴论拼装&quot;可验证、局部保真&quot;的基础模型&quot;">​</a></h3><p><strong>原文</strong>：arXiv: <a href="https://arxiv.org/abs/2606.27593" target="_blank" rel="noreferrer">2606.27593</a> 论文提出 ODYSSEY 框架，把基础模型视为由&quot;foundry（铸造厂）&quot;组合而成的范畴。这是一个<strong>形式化、可验证</strong>的模型架构理论，承诺在不重新训练的前提下保证输出在&quot;局部真理&quot;约束内。</p><p><strong>深度扩展</strong>：</p><p>正式题名 <em>Odyssey: Constructing Verifiable Local Truth-Preserving Foundation Models</em>（arXiv:2606.27593）。它的数学骨架是<strong>层论（sheaf theory）</strong>，这一点比简讯的&quot;范畴论&quot;更具体：一个 foundry 被定义为一个组织化的知识层，必须同时给出六件东西——局部上下文的一个覆盖（cover）、局部表示族、限制映射（restriction map）、粘合规则（gluing rule）、障碍策略（obstruction policy）、更新义务（update obligation），再加一个面向人的视图。通俗说：它规定了&quot;什么情况下两块局部知识可以拼起来、拼不起来怎么办、拼完之后谁负责更新&quot;。</p><p>论文的关键构件是 Universal Foundry Learning（UFL），把 foundry 的构造形式化为<strong>左 Kan 扩张与右 Kan 扩张的复合</strong>：左 Kan 扩张负责把零散的局部产物&quot;卷&quot;成候选 foundry（广度），右 Kan 扩张负责强制满足限制、粘合、障碍与论证条件（合法性）。层论的公理在这里承担了&quot;审计员&quot;的角色——粘合失败就是被结构性地检出，而不是靠事后评测发现。</p><p>必须说清边界：这是一篇<strong>理论框架</strong>论文，给出的是可验证性的数学条件与构造流程，不提供大规模实验数字。&quot;不重新训练即可保证局部真理&quot;是可证明的<strong>条件性</strong>承诺——前提是 foundry 的局部表示确实满足它声明的义务。真正的价值在于，它把&quot;模型能否签合同&quot;这个法律问题，转写成了&quot;局部真理能否粘合&quot;这个数学问题。</p><p><strong>跨主题关联</strong>：<code>topics/philosophy/index.md</code>（真理的局部性与整体性）、<code>topics/ai-system-architecture/index.md</code>（可验证架构）、<code>topics/cross-domain-synthesis-2026-q3.md</code>（&quot;约束-涌现&quot;模式）。</p><hr><h3 id="_11-符号反馈驱动的规划自我精炼-把-能跑通-变成闭环" tabindex="-1">11. 符号反馈驱动的规划自我精炼：把&quot;能跑通&quot;变成闭环 <a class="header-anchor" href="#_11-符号反馈驱动的规划自我精炼-把-能跑通-变成闭环" aria-label="Permalink to &quot;11. 符号反馈驱动的规划自我精炼：把&quot;能跑通&quot;变成闭环&quot;">​</a></h3><p><strong>原文</strong>：arXiv: <a href="https://arxiv.org/abs/2606.27757" target="_blank" rel="noreferrer">2606.27757</a> 针对 LLM 在长视野规划中&quot;输出不可行解&quot;的痛点，这篇工作提出<strong>符号反馈 + 迭代自我精炼</strong>的闭环，把&quot;可行解比例&quot;从 ~40% 提升到 90%+。</p><p><strong>深度扩展</strong>：</p><p>正式题名 <em>Towards Reliable and Robust LLM Planning: Symbolic Feedback-Driven Iterative Self-Refinement Framework</em>（arXiv:2606.27757）。它由三个可拆的部件组成，值得分别看：</p><p>一，<strong>符号→自然语言的映射提示</strong>。规划问题本来以 PDDL 一类形式语言给出，模型对形式约束的敏感度远低于对自然语言描述的敏感度；作者把逻辑符号翻成自然语言描述再喂给模型，让约束&quot;进入语用层&quot;，这是低成本但见效的一步。</p><p>二，<strong>符号验证器 + 纠错指令</strong>。验证器判定计划是否可行，并把错误<strong>转译成模型能读懂的自然语言纠正指令</strong>——关键在&quot;转译&quot;，直接把 &quot;unsolvable&quot; 抛回给模型通常只会引发换个说法的重复犯错。</p><p>三，<strong>计划识别器（plan recognizer）</strong>。用来推断目标可达性，避免在根本无解的目标上空转——这是防止迭代陷入死循环的保险丝。</p><p>整体是&quot;生成→验证→解释→重生成&quot;的循环，直到验证通过。这类框架的通用意义在于：它把&quot;LLM 写代码能编译通过&quot;这一成功范式，迁移成&quot;LLM 写流程能执行通过&quot;。对企业流程自动化（ERP 操作、工作流编排）尤其对症，因为历史上 agent 最典型的失败模式正是&quot;看起来完全合理，但跑不通&quot;。</p><p><strong>跨主题关联</strong>：<code>topics/ai-tools/index.md</code>（agent 工具链）、<code>topics/ai-system-architecture/index.md</code>（验证器与生成器的分离）、<code>topics/vibe-coding/index.md</code>（&quot;生成-验证&quot;闭环在编程场景的同构）。</p><hr><h2 id="🧠-机制层" tabindex="-1">🧠 机制层 <a class="header-anchor" href="#🧠-机制层" aria-label="Permalink to &quot;🧠 机制层&quot;">​</a></h2><h3 id="机制一-镍酸盐为什么-像铜氧化物-——从-nio2-平面到磁涨落配对" tabindex="-1">机制一：镍酸盐为什么&quot;像铜氧化物&quot;——从 NiO₂ 平面到磁涨落配对 <a class="header-anchor" href="#机制一-镍酸盐为什么-像铜氧化物-——从-nio2-平面到磁涨落配对" aria-label="Permalink to &quot;机制一：镍酸盐为什么&quot;像铜氧化物&quot;——从 NiO₂ 平面到磁涨落配对&quot;">​</a></h3><p>铜氧化物高温超导的核心结构是 CuO₂ 平面：一个 Cu 的 3dₓ²₋ᵧ² 轨道与两个 O 的 2p 轨道杂化，形成半满的单带，反铁磁超交换 J 提供强关联背景。镍酸盐被寄予厚望，就是因为 NiO₂ 平面在几何上完全同构——但镍是 3d⁸ 而不是 3d⁹，多出一个电子会落到 d_z² 轨道，从而冒出一条额外的自旋三重态能带。这既是镍酸盐与铜氧化物的分水岭，也是它可能更复杂的原因。</p><p>2026 年这两篇 Science 提供的是一份<strong>因果链的两端</strong>。</p><p>上游（<code>10.1126/science.adp4440</code>，哈佛组）：用 Ndₙ₊₁NiₙO₂ₙ₊₂ 的维度 n 当旋钮，n 从 4 变到 8，实际是在调节 NiO₂ 层被 Nd 层隔开的程度。n 越小，层间耦合越强，超导各向异性越大；4f 电子效应随 n 改变有效掺杂，使电子结构逐步向 cuprate-like 靠拢。最关键的一条是磁涨落的<strong>相图位置</strong>：它不只在超导穹顶内出现，而是一路延伸到过掺杂的非超导区。若磁涨落只是超导的产物，它应当在 T_c 消失处一起消失；它越界存活，说明磁涨落是<strong>外在于超导态的母体涨落</strong>，超导只是它在某个掺杂窗口内的凝聚结果——这正是铜氧化物领域争论三十年的判据，镍酸盐把它变成了在同一材料家族内逐层比较的对照实验。</p><p>下游（<code>10.1126/science.adw8329</code>，中科大组）：ARPES 直接测能隙结构。约 18 meV 的能隙沿布里渊区对角线出现相干峰，且整个布里渊区都能测到有限能隙、没有节点。无节点能隙排除了 d 波配对（d 波必然在对角线上有节点），把配对对称性收窄到 s± 或 s+d 混合。进一步由能隙的温度依赖反解出的电子-玻色子耦合谱，其峰位对应一个明确的玻色子能量尺度——这正是&quot;磁涨落当配对胶水&quot;的定量指纹。</p><p>把两端接起来，链条是：NiO₂ 平面几何 → 3d 多轨道使 d_z² 带介入 → 层间超交换产生强磁涨落 → 磁涨落跨越超导边界存活 → 无节点能隙与特征玻色子能量出现 → 高温超导。<strong>每个箭头现在都有独立实验支撑</strong>，而不是同一个宏观现象的自证循环。这也解释了相图为何长成穹顶而非台阶：配对强度与过掺杂/无序抑制是两条方向相反的曲线，乘积必然是钟形。</p><p>尚未闭合的一环是 d_z² 带的确切角色。若它真的贡献配对分量，自旋分辨或中子散射应能看到配对态内部的自旋结构各向异性——这是一个明确、可证伪的下一步。</p><h3 id="机制二-同一个视黄醛-三种吸收峰——视锥光谱调谐的静电学" tabindex="-1">机制二：同一个视黄醛，三种吸收峰——视锥光谱调谐的静电学 <a class="header-anchor" href="#机制二-同一个视黄醛-三种吸收峰——视锥光谱调谐的静电学" aria-label="Permalink to &quot;机制二：同一个视黄醛，三种吸收峰——视锥光谱调谐的静电学&quot;">​</a></h3><p>11-顺视黄醛通过质子化的 Schiff 碱共价挂在视蛋白的 Lys 残基上。光子被吸收时发色团发生 11-顺→全反异构化，把光能转成蛋白构象变化。吸收波长由基态与激发态之间的能隙决定，而这个能隙几乎完全由<strong>发色团所处的静电环境</strong>调谐——这是视觉化学的中心事实，2026 年这三篇 Science 第一次把它在接近原子分辨率上读了出来。</p><p>第一步，<strong>口袋极性决定 Schiff 碱的质子化态能量</strong>。质子化 Schiff 碱（PSB）在激发态高度电荷转移，激发态偶极矩显著大于基态。口袋内带负电或强极性的残基若靠近 PSB，会优先稳定激发态，能隙变小、吸收红移；若被疏水残基包围、或用氢键把电荷锁死，激发态得不到稳定，能隙变大、吸收蓝移。蓝敏 OPN1SW 与绿敏 OPN1MW 只差少量残基，吸收峰却差约 110 nm，这个差距必须由少数位点的静电场差解释——正是 <code>10.1126/science.adz3624</code> 用冷冻电镜 + 飞秒光谱 + 静电计算联合定量的对象。</p><p>第二步，<strong>反离子位置是主开关</strong>。视紫红质里 Glu113 作为反离子中和 PSB；视锥中对应位点的微调会改变 PSB 的 pKa。pKa 一变，质子化平衡移动，吸收峰与光稳定性同时改变。</p><p>第三步，<strong>发色团被&quot;撑开或夹紧&quot;的构象张力</strong>。口袋体积决定 β-紫罗兰酮环的扭转角，扭转角决定 π 共轭的有效长度——共轭越长，能隙越小。这解释了&quot;同一个零件&quot;如何出三种颜色：不是换了染料，是换了夹具。</p><p>第四步，<strong>微开关决定响应速度</strong>。GPCR 的 DRY 与 NPxxY 基序在视锥中序列特化，使 Meta II 态更易形成也更易失活，视锥因此能在毫秒量级复位；视杆的视紫红质慢一个数量级。这是白天视觉与夜间视觉在分子层面的分工：视杆把灵敏度推到单光子极限，代价是慢；视锥把时间分辨率做到极致，代价是需要强光。</p><p>可证伪预测很直接：把三个色素口袋中被指认的关键极性位点做互换突变，吸收峰应按静电模型预测的方向偏移数十纳米，且 pKa 与该位点的介电环境相关。<code>adz3996</code> 与 <code>adz8141</code> 提供的正是这种&quot;逐位点可对照&quot;的结构基线。</p><h3 id="机制三-磁场为什么会-帮-超导——时间反演对称性的独立破缺" tabindex="-1">机制三：磁场为什么会&quot;帮&quot;超导——时间反演对称性的独立破缺 <a class="header-anchor" href="#机制三-磁场为什么会-帮-超导——时间反演对称性的独立破缺" aria-label="Permalink to &quot;机制三：磁场为什么会&quot;帮&quot;超导——时间反演对称性的独立破缺&quot;">​</a></h3><p>常规 BCS 超导里磁场是敌人，原因有二：轨道效应（洛伦兹力弯曲库珀对轨迹、破坏相位相干）与 Pauli 效应（塞曼劈裂把自旋单态电子拉向平行、拆散配对）。Pauli 极限 B_p ≈ 1.84 T_c（T/K）就是后者的定量表达。任何&quot;面内磁场下超导不灭反强&quot;的现象，都必须绕过这两条。</p><p><code>10.1038/s41586-026-10815-x</code> 在菱面体五层石墨烯里看到：面内场直到 8.5 T 仍稳定，超出 Pauli 极限数十倍；面外场也能增强。</p><p>绕过的机制是<strong>时间反演对称性（TRS）与规范对称性分离地破缺</strong>。寻常超导体里，破缺规范对称性（形成库珀对）几乎锁定配对通道：要么自旋单态（被 Pauli 效应杀），要么在三重态通道被强自旋轨道耦合锁死。但在非常规体系里，配对可在<strong>有限中心波矢</strong>处形成——FFLO 态，库珀对带有限动量 q，电子在塞曼劈裂的两条费米面之间配对。这时磁场不再是破坏者，而是<strong>配对的必要条件</strong>：没有塞曼劈裂，就没有可供配对的失配费米面。</p><p>另一条通道是<strong>同位旋配对</strong>。菱面体多层石墨烯的本征平带附近携带近似的自旋-谷 SU(2) 对称性，配对可以发生在&quot;谷&quot;而非&quot;自旋&quot;这个自由度上。面内磁场此时起两个作用：抑制自旋单态通道（关掉竞争相），并把系统推入&quot;谷单态/自旋三重态&quot;的窗口。磁场从破坏者变成<strong>选择器</strong>。</p><p>五层体系比双层的关键优势在能带平坦度。平带意味着态密度在很宽的栅压范围内都高、费米面小、有效质量大，同样的关联能标只需低得多的载流子密度与栅极电场即可达到——实验窗口宽、无序敏感度低（论文强调 clean-limit）。也正因平带，超导相在相图上呈<strong>多分支</strong>：三种不同类型的场增强/场诱导超导，加上邻近自旋轨道耦合再&quot;生&quot;出的多个相，说明这是由对称性通道决定的多分支相图，而非单一机制的不同表现。</p><p>可证伪预测三条：一，若为 FFLO，超导应出现在有限中心波矢，约瑟夫森/界面实验应测到 q≠0 的振荡；二，若为同位旋配对，自旋极化测量应显示配对态在自旋通道&quot;惰性&quot;、而谷极化敏感；三，场增强相 T_c 对面内场角度应有各向异性，且各向异性轴由晶格对称性（而非磁场方向）决定。任意一条被否定，就排除对应分支。</p><hr><h2 id="⚛️-第一性原理层" tabindex="-1">⚛️ 第一性原理层 <a class="header-anchor" href="#⚛️-第一性原理层" aria-label="Permalink to &quot;⚛️ 第一性原理层&quot;">​</a></h2><h3 id="原理一-视界只有两个数——为什么-直接波-必须出现在-2ω-h" tabindex="-1">原理一：视界只有两个数——为什么&quot;直接波&quot;必须出现在 2Ω_H <a class="header-anchor" href="#原理一-视界只有两个数——为什么-直接波-必须出现在-2ω-h" aria-label="Permalink to &quot;原理一：视界只有两个数——为什么&quot;直接波&quot;必须出现在 2Ω_H&quot;">​</a></h3><p>黑洞视界是因果结构的边界：它是未来光锥的生成面，&quot;内部&quot;按定义无法向&quot;外部&quot;发送信号。由此推出一个非常强的约束——外部观测者能接收到的关于视界的全部信息，只能来自<strong>贴着视界外侧传播</strong>的那部分场，而稳态轴对称视界在局域上只由两个量刻画：角速度 Ω_H 与表面重力 κ。这是&quot;无毛&quot;的几何版本：不是&quot;黑洞没有特征&quot;，而是&quot;黑洞外部可读的特征被压缩成两个数&quot;。</p><p>于是观测上的推论是唯一的：任何落入视界的扰动，其辐射必然被两件事编码。时间尺度上，它被参考系拖曳强行锁定在以 Ω_H 转动的坐标系里，信号因此以与 2Ω_H 相关的频率振荡（2 倍来自度规扰动的自旋-2 结构，h_μν 在绕轴旋转 180° 后回到自身）；振幅上，它必须按 e^(−κt) 衰减，因为 κ 正是&quot;红移因子沿法向的导数&quot;，即外部时间与视界附近固有时之间的换算率。这两个量都不是拟合参数，而是直接从 Kerr 度规读出的。</p><p>这就把 GW250114 的检验变成了一次纯粹的几何检验：测到 2Ω_H 附近的振荡 + 由 κ 决定的衰减率 + 二者与质量、自旋的自洽，等价于直接确认&quot;那里有一个满足因果边界条件的面&quot;。测到 15.8/17.1 的匹配滤波信噪比并吻合理论，意味着这个面在强场动力学中真实存在。</p><p>更深的含义是可证伪性：如果引力理论偏离广义相对论（例如引入额外的标量自由度），视界附近会出现&quot;毛&quot;，则 2Ω_H 附近的振荡结构会被附加模式污染，或 κ 与 (M, χ) 的关系被改写。因此任何替代引力理论都必须预测一个不同的 (频率, 衰减率) 组合——这是一个能把理论逐一出局的判据，而不是只能被&quot;证实&quot;的叙事。</p><h3 id="原理二-pauli-极限是费米统计的直接推论——超越它就必须换自由度" tabindex="-1">原理二：Pauli 极限是费米统计的直接推论——超越它就必须换自由度 <a class="header-anchor" href="#原理二-pauli-极限是费米统计的直接推论——超越它就必须换自由度" aria-label="Permalink to &quot;原理二：Pauli 极限是费米统计的直接推论——超越它就必须换自由度&quot;">​</a></h3><p>Pauli 极限可以一行推完。自旋单态库珀对的凝聚能约为 Δ₀ ≈ 1.76 k_B T_c；塞曼能劈裂为 2μ_B B（μ_B 为玻尔磁子）。当塞曼能在凝聚能之上，拆对在能量上更划算，超导被破坏。令二者相等，得到 B_p = Δ₀/(√2 μ_B) ≈ 1.84 T_c（T/K 单位）。这个数里没有任何材料参数，它是<strong>费米统计 + 电磁耦合</strong>的直接结果。</p><p>所以&quot;超出 Pauli 极限数十倍&quot;这句话本身就是一则排除性证据：在没有强自旋轨道耦合的体系中，普通自旋单态配对不可能越过这条线。逻辑上只剩三条出路——(a) 配对发生在自旋以外的自由度上（谷、层、同位旋），使塞曼场无法直接拆对；(b) 库珀对带有限中心动量（FFLO），用动能失配换取配对，使磁场成为必要条件；(c) 强自旋轨道耦合把自旋与动量锁定，削弱塞曼场的拆对效力（Ising 保护）。</p><p>菱面体多层石墨烯恰好同时具备 (a) 与 (b) 的前提：本征平带带来近似的自旋-谷 SU(2) 对称性，且费米面小而态密度高，FFLO 所需的失配费米面容易构造。论文报告的三种场增强/场诱导超导与&quot;邻近 SOC 又生成多个新相&quot;，也符合&quot;多通道共存&quot;的预期：SOC 越强，(c) 通道越参与，相图分支越多。</p><p>这条原理的可操作价值在于给出<strong>判定树的顶层节点</strong>：先看面内/面外场响应差异，就能区分&quot;自旋通道是否被绕过&quot;；再看 T_c 随场角的各向异性轴由晶格还是磁场决定，就能区分 Ising 保护与 FFLO。这是一种&quot;用对称性做实验设计&quot;的思路——不必先知道微观机制，也能用宏观响应把机制空间切块。</p><hr><h2 id="🔗-交叉关联" tabindex="-1">🔗 交叉关联 <a class="header-anchor" href="#🔗-交叉关联" aria-label="Permalink to &quot;🔗 交叉关联&quot;">​</a></h2><p>本期 11 条表面分散在天体物理、超导、结构生物学、遗传学、材料学与 AI，但有两条统一逻辑贯穿。</p><p><strong>第一条：可见性由约束条件定义，而非由对象本身定义。</strong> 黑洞视界内部永远不可见，但 Ω_H 与 κ 这两个&quot;约束的导数&quot;把视界变成了可测对象；镍酸盐的磁涨落因为越出超导边界存活，才被判定为母体涨落而非产物；精神疾病的风险位点只有在神经元被激活这一特定约束下才显效；ODYSSEY 的层论则把&quot;局部真理能否粘合&quot;写成了可审计的约束。四件事的方法论完全同构：<strong>不是直接观测对象，而是观测&quot;边界在哪里、约束怎么变&quot;</strong>。这与库内 <code>topics/philosophy/index.md</code> 的&quot;局部性与整体性&quot;、<code>topics/cross-domain-synthesis-2026-q3.md</code> 的&quot;约束-涌现&quot;模式是同一件事的不同投影。</p><p><strong>第二条：突破来自换一个自由度，而不是把旧自由度做到极致。</strong> 视锥不是造出三种染料，而是让同一个视黄醛在不同夹具里共振——换的是静电环境；石墨烯超导不是把磁场压得更小，而是让配对发生在&quot;谷&quot;而非&quot;自旋&quot;上——换的是配对自由度；2400 °C 合金不是在镍基里继续微调，而是换到 Ta + HfO₂ 的晶内弥散——换的是强化相与基体的组合方式；AI 侧同样：<code>2606.27483</code> 不是把 agent 的反思轮数加多，而是把世界模型从外挂模块换进策略内部；<code>2606.27593</code> 不是堆评测，而是把合法性换成可证明的粘合条件；<code>2606.27757</code> 不是让模型&quot;再想一遍&quot;，而是把验证器换成一个会说人话的符号审计员。</p><p>两条逻辑合起来，正好对应本库&quot;AI 外脑&quot;的核心工程判断：<strong>知识网络的价值不在存储量，而在关联的约束结构</strong>（第一条）；而外脑的升级路径不在&quot;记得更多&quot;，而在&quot;换一层表征&quot;——从关键词到语义、从文档到图谱（第二条）。<code>topics/ai-brain/index.md</code> 与 <code>topics/intelligence-self-learning/index.md</code> 记录的自进化路线，本质上就是这两条原理的工程化。</p><p>值得单独标注的一处跨日对读：<code>10.1126/science.adp4440</code>（镍酸盐相图）在 2026-07-02 的日报中也出现过，两天的解读角度不同（07-02 侧重相图本身，本篇侧重力争把 ARPES 结果接成完整因果链），可与 <code>science-daily/2026-07-02.md</code> 并读，正好构成同一材料体系的&quot;上游相图 + 下游能隙&quot;双视角。</p><hr><p>关键词：镍酸盐, nickelate, 超导相图, Nd(n+1)NinO(2n+2), 无节点能隙, nodeless gap, 电子-玻色子耦合, electron-boson coupling, ARPES, 10.1126/science.adp4440, 10.1126/science.adw8329, Mundy, 哈佛大学, GW250114, 直接波, direct wave, 视界角速度, 表面重力, Kerr 黑洞, 匹配滤波, SNR 15.8, 10.1038/s41586-026-10696-0, 陈雁北, 视锥色素, cone opsin, OPN1SW, OPN1MW, 冷冻电镜, cryo-EM, 视黄醛, retinal, Schiff 碱, 光谱调谐, 10.1126/science.adz3624, 10.1126/science.adz3996, 10.1126/science.adz8141, 单细胞多组学, single-nucleus multiomics, 染色质可及性, iPSC, 精神疾病遗传力, GWAS, 10.1126/science.adw3949, 芝加哥大学, 菱面体石墨烯, rhombohedral graphene, 磁场增强超导, Pauli 极限, FFLO, 同位旋配对, 自旋轨道耦合, 10.1038/s41586-026-10815-x, 康奈尔大学, 难熔合金, Ta 基合金, HfO2 弥散强化, 原位氧化, 抗拉强度, 2400°C, Ostwald 熟化, 10.1038/s41586-026-10708-z, AI-ModelNet, AI 模型网络, arXiv:2606.27382, 多智能体人格, personality composition, arXiv:2606.27443, 世界模型, format-capability gap, WM-AMT, arXiv:2606.27483, ODYSSEY, foundry, 层论, sheaf, Kan 扩张, arXiv:2606.27593, 符号反馈, 规划自我精炼, 验证器, arXiv:2606.27757, Nature, Science, arXiv, CrossRef, EuropePMC</p><p>关联：topics/physics/index.md, topics/quantum-physics/index.md, topics/materials/index.md, topics/neuroscience/index.md, topics/biomedicine/index.md, topics/ai-system-architecture/index.md, topics/ai-tools/index.md, topics/ai-brain/index.md, topics/intelligence-self-learning/index.md, topics/vibe-coding/index.md, topics/psychology/index.md, topics/philosophy/index.md, topics/wind-energy/index.md, topics/space-energy/index.md, topics/science-news/index.md, topics/cross-domain-synthesis-2026-q3.md</p>',143)])])}const l=t(a,[["render",i]]);export{g as __pageData,l as default};
